UNION ALL
SELECT order_id, customer_name, amount FROM warehouse_orders;

startingSql:
SELECT e.name
FROM employees e
WHERE EXISTS (
  SELECT 1 FROM employees e2 WHERE e2.salary = e.salary
);

solutionSql:
SELECT e.name
FROM employees e
WHERE EXISTS (
  SELECT 1 FROM employees e2 WHERE e2.salary = e.salary AND e2.id <> e.id
);

startingSql:
SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING), 2) AS trailing_avg
FROM employees;

solutionSql:
SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS trailing_avg
FROM employees;

